   "source": [
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "from sklearn.decomposition import PCA\n",
    "from PIL import Image"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "fe6a864b-6b1b-4ce6-9dce-c9cddf127f09",
   "metadata": {},
   "source": [
