  {
   "cell_type": "code",
   "execution_count": 2,
   "id": "a3fd0e94-aa88-4d24-96e4-9fad0e7e2055",
   "metadata": {},
   "outputs": [],
   "source": [
    "image_path = 'unal.png'\n",
    "image = Image.open(image_path)"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "291af424-bf12-4e36-87ba-7f9a990d60d5",
   "metadata": {},
   "source": [
    "# Imagen original"
   ]
  },
