     "output_type": "display_data"
    }
   ],
   "source": [
    "plt.imshow(image)\n",
    "plt.axis('off')\n",
    "plt.title('Imagen Original')\n",
    "plt.show()"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "5d3aabed-03e9-4e48-bd19-14f508ee21a8",
   "metadata": {},
   "source": [
    "# Conversión de la imagen\n",
    "\n",
    "Convierte la imagen a formato RGB (elimina el canal alfa)"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 4,
   "id": "9d9de4a2-b8cb-4aee-ab78-090643a370de",
   "metadata": {},
   "outputs": [],
   "source": [
    "image_rgb = image.convert('RGB')"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "289b94c2-c5de-4cfb-b301-b13e47b33362",
   "metadata": {},
   "source": [
    "#  Converión a Matriz\n",
    "\n",
    "Se convierte la imagen en una matriz numpy"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 5,
   "id": "ed4fb0d8-074b-4fc2-a667-c2f82744775c",
   "metadata": {},
   "outputs": [],
   "source": [
    "image_array_alpha = np.array(image)\n",
    "image_array = np.array(image_rgb)"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 6,
   "id": "1d900b2c-edb5-49be-b9b6-ff1b91ebbeae",
   "metadata": {},
   "outputs": [
    {
     "name": "stdout",
     "output_type": "stream",
     "text": [
      "Las dimensiones con el canal alfa son: (500, 1109, 4)\n",
      "Las dimensiones quitando el canal alfa son: (500, 1109, 3)\n"
     ]
    }
   ],
   "source": [
    "print(f'Las dimensiones con el canal alfa son: {image_array_alpha.shape}')\n",
    "print(f'Las dimensiones quitando el canal alfa son: {image_array.shape}')"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "8aa4df4b-b988-4d32-a4ac-acc7062ffa8e",
   "metadata": {},
   "source": [
