    "print('La varianza explicada por cada una de las componentes principales es:', pca_25.explained_variance_ratio_, end='\\n\\n')\n",
    "\n",
    "print('La varianza total explicada por las componentes es:', np.sum(pca_25.explained_variance_ratio_), end='\\n\\n')"
   ]
