   "metadata": {},
   "outputs": [],
   "source": [
    "reconstructed_pixels_5 = pca_5.inverse_transform(pixels_pca_5)\n",
    "\n",
    "# Se reescalan los datos\n",
    "reconstructed_pixels_5 = reconstructed_pixels_5 * 255.0\n",
    "\n",
    "# Redimensiona la matriz reconstruida a la forma de la imagen original\n",
    "reconstructed_image_array_5 = reconstructed_pixels_5.reshape(image_array.shape)\n"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 19,
